package com.madar.files;

import android.graphics.*;
import android.text.*;
import org.json.*;
import java.io.*;
import java.util.*;
import java.util.zip.ZipOutputStream;

/** One writer for native PDF geometry and validated vision blocks. No layout tables. */
final class EditableWord {
 static String run(String text,double size,boolean rtl,boolean bold,boolean italic,String font){
  StringBuilder out=new StringBuilder("<w:r><w:rPr><w:rFonts w:ascii=\"").append(LayoutWordExporter.xml(font)).append("\" w:hAnsi=\"").append(LayoutWordExporter.xml(font)).append("\" w:cs=\"").append(LayoutWordExporter.xml(font)).append("\"/><w:sz w:val=\"").append(Math.round(size*2)).append("\"/><w:szCs w:val=\"").append(Math.round(size*2)).append("\"/>").append(rtl?"<w:rtl/>":"<w:rtl w:val=\"0\"/>").append(bold?"<w:b/><w:bCs/>":"").append(italic?"<w:i/><w:iCs/>":"").append("</w:rPr>");
  String[] lines=text.split("\\n",-1);for(int l=0;l<lines.length;l++){if(l>0)out.append("<w:br/>");String[] tabs=lines[l].split("\\t",-1);for(int t=0;t<tabs.length;t++){if(t>0)out.append("<w:tab/>");out.append("<w:t xml:space=\"preserve\">").append(LayoutWordExporter.xml(tabs[t])).append("</w:t>");}}return out.append("</w:r>").toString();
 }
 static String paragraph(JSONObject block,double size)throws Exception{
  String text=block.getString("text");boolean rtl=CloudDocuments.isRtl(text);String align=block.optString("alignment",rtl?"right":"left");if(!Arrays.asList("left","right","center","justify").contains(align))align=rtl?"right":"left";
  // Word mirrors physical left/right paragraph justification in bidi paragraphs.
  if(rtl&&align.equals("right"))align="left";else if(rtl&&align.equals("left"))align="right";
  StringBuilder out=new StringBuilder("<w:p><w:pPr><w:spacing w:before=\"0\" w:after=\"0\"/>").append(rtl?"<w:bidi/>":"").append("<w:jc w:val=\"").append(align.equals("justify")?"both":align).append("\"/></w:pPr>");
  JSONArray runs=block.optJSONArray("runs");if(runs==null)runs=new JSONArray().put(new JSONObject().put("text",text).put("bold",block.optBoolean("bold")).put("italic",block.optBoolean("italic")).put("font",block.optString("font","Arial")));
  for(int i=0;i<runs.length();i++){JSONObject r=runs.getJSONObject(i);String value=r.getString("text");java.util.regex.Matcher latin=java.util.regex.Pattern.compile("[A-Za-z0-9][A-Za-z0-9 .,:/%+\\-]*").matcher(value);int at=0;while(latin.find()){if(latin.start()>at)out.append(run(value.substring(at,latin.start()),size,rtl,r.optBoolean("bold"),r.optBoolean("italic"),r.optString("font","Arial")));out.append(run(latin.group(),size,false,r.optBoolean("bold"),r.optBoolean("italic"),r.optString("font","Arial")));at=latin.end();}if(at<value.length())out.append(run(value.substring(at),size,rtl,r.optBoolean("bold"),r.optBoolean("italic"),r.optString("font","Arial")));if(value.isEmpty())out.append(run("",size,rtl,false,false,"Arial"));}
  return out.append("</w:p>").toString();
 }
 static double fittedSize(JSONObject b,double width,double height){double size=b.optDouble("fontSize",12);String text=b.optString("text");if(text.isEmpty())return size;TextPaint paint=new TextPaint(Paint.ANTI_ALIAS_FLAG);paint.setTypeface(Typeface.create(b.optString("font","Arial"),b.optBoolean("bold")?Typeface.BOLD:Typeface.NORMAL));
  for(int n=0;n<10;n++){paint.setTextSize((float)(size*3*1.10));StaticLayout layout=StaticLayout.Builder.obtain(text,0,text.length(),paint,Math.max(1,(int)(width*3))).setIncludePad(false).setTextDirection(CloudDocuments.isRtl(text)?TextDirectionHeuristics.RTL:TextDirectionHeuristics.LTR).build();if(layout.getHeight()<=height*3+3||size<=6)break;size=Math.max(6,size*.94);}return size;
 }
 static List<JSONObject> ordered(JSONArray source)throws Exception{List<JSONObject> blocks=new ArrayList<>(),out=new ArrayList<>();for(int i=0;i<source.length();i++)blocks.add(source.getJSONObject(i));order(blocks,out,0);return out;}
 private static void order(List<JSONObject> blocks,List<JSONObject> out,int depth){if(blocks.size()<2){out.addAll(blocks);return;}if(depth>30){blocks.sort(Comparator.comparingDouble(b->b.optDouble("y")));out.addAll(blocks);return;}for(String axis:new String[]{"y","x"}){String extent=axis.equals("y")?"h":"w";List<JSONObject> sorted=new ArrayList<>(blocks);sorted.sort(Comparator.comparingDouble(b->b.optDouble(axis)));double end=sorted.get(0).optDouble(axis)+sorted.get(0).optDouble(extent);for(int i=1;i<sorted.size();i++){JSONObject b=sorted.get(i);if(b.optDouble(axis)-end>.006){List<JSONObject> first=new ArrayList<>(sorted.subList(0,i)),second=new ArrayList<>(sorted.subList(i,sorted.size()));boolean rtl=false;if(axis.equals("x")){long ar=0,latin=0;for(JSONObject item:blocks){String t=item.optString("text");ar+=t.codePoints().filter(c->Character.UnicodeScript.of(c)==Character.UnicodeScript.ARABIC).count();latin+=t.codePoints().filter(c->Character.UnicodeScript.of(c)==Character.UnicodeScript.LATIN).count();}rtl=ar>latin;}order(rtl?second:first,out,depth+1);order(rtl?first:second,out,depth+1);return;}end=Math.max(end,b.optDouble(axis)+b.optDouble(extent));}}blocks.sort(Comparator.comparingDouble(b->b.optDouble("y")));out.addAll(blocks);}
 static String page(ZipOutputStream zip,JSONObject page,Bitmap bitmap,double width,double height,int pageIndex,boolean positioned)throws Exception{
  StringBuilder body=new StringBuilder();int index=0;double cursor=0;for(JSONObject b:ordered(page.getJSONArray("blocks"))){String type=b.getString("type");double x=b.getDouble("x")*width,y=b.getDouble("y")*height,w=b.getDouble("w")*width,h=b.getDouble("h")*height;
   if(type.equals("table")){String table=CloudDocuments.table(b,width,height);if(!positioned)table=table.replaceAll("<w:tblpPr[^>]*/>","");body.append(table);cursor=Math.max(cursor,y+h);index++;continue;}
   if(type.equals("text")){
    double size=positioned?fittedSize(b,w,h):b.optDouble("fontSize",12);String paragraph=paragraph(b,size);
    if(positioned){String style=LayoutWordExporter.style((float)x,(float)y,(float)w,(float)(h+2));body.append("<w:p><w:pPr><w:spacing w:line=\"1\" w:lineRule=\"exact\" w:before=\"0\" w:after=\"0\"/></w:pPr><w:r><w:pict><v:shape id=\"paragraph_").append(pageIndex).append('_').append(index).append("\" style=\"").append(style).append("\" filled=\"f\" stroked=\"f\"><v:textbox inset=\"0,0,0,0\" style=\"mso-fit-shape-to-text:t\"><w:txbxContent>").append(paragraph).append("</w:txbxContent></v:textbox></v:shape></w:pict></w:r></w:p>");}
    else{double gap=Math.min(24,Math.max(0,y-cursor));paragraph=paragraph.replace("w:before=\"0\"","w:before=\""+Math.round(gap*20)+"\"");long left=Math.max(0,Math.round(x*20)),right=Math.max(0,Math.round((width-x-w)*20));if(CloudDocuments.isRtl(b.optString("text"))){long swap=left;left=right;right=swap;}paragraph=paragraph.replace("</w:pPr>","<w:ind w:left=\""+left+"\" w:right=\""+right+"\"/></w:pPr>");body.append(paragraph);}cursor=Math.max(cursor,y+h);
   }else if(type.equals("image")){
    if(bitmap==null)throw new IOException("صورة المصدر غير متاحة");int px=Math.max(0,Math.min(bitmap.getWidth()-1,(int)Math.floor(b.getDouble("x")*bitmap.getWidth()))),py=Math.max(0,Math.min(bitmap.getHeight()-1,(int)Math.floor(b.getDouble("y")*bitmap.getHeight())));int pw=Math.max(1,Math.min(bitmap.getWidth()-px,(int)Math.ceil(b.getDouble("w")*bitmap.getWidth()))),ph=Math.max(1,Math.min(bitmap.getHeight()-py,(int)Math.ceil(b.getDouble("h")*bitmap.getHeight())));Bitmap crop=Bitmap.createBitmap(bitmap,px,py,pw,ph);ByteArrayOutputStream bytes=new ByteArrayOutputStream();try{crop.compress(Bitmap.CompressFormat.PNG,100,bytes);}finally{if(crop!=bitmap)crop.recycle();}if(bytes.size()>8*1024*1024)throw new IOException("صورة المستند كبيرة جدًا");String id="p"+pageIndex+"_"+index;LayoutWordExporter.entry(zip,"word/media/"+id+".png",bytes.toByteArray());String picture=picture(id,x,y,w,h,index+1,positioned);if(!positioned)picture=picture.replace("</w:pPr>","<w:keepNext/><w:ind w:left=\""+Math.round(x*20)+"\"/></w:pPr>");body.append(picture);cursor=Math.max(cursor,y+h);
   }else throw new IOException("نوع عنصر غير صالح");index++;
  }return body.toString();
 }
 static String picture(String id,double x,double y,double w,double h,int index,boolean positioned){long cx=Math.round(w*12700),cy=Math.round(h*12700);String start=positioned?"<wp:anchor distT=\"0\" distB=\"0\" distL=\"0\" distR=\"0\" simplePos=\"0\" relativeHeight=\"0\" behindDoc=\"0\" locked=\"0\" layoutInCell=\"1\" allowOverlap=\"1\"><wp:simplePos x=\"0\" y=\"0\"/><wp:positionH relativeFrom=\"page\"><wp:posOffset>"+Math.round(x*12700)+"</wp:posOffset></wp:positionH><wp:positionV relativeFrom=\"page\"><wp:posOffset>"+Math.round(y*12700)+"</wp:posOffset></wp:positionV>":"<wp:inline distT=\"0\" distB=\"0\" distL=\"0\" distR=\"0\">";return "<w:p><w:pPr><w:spacing w:before=\"0\" w:after=\"0\"/></w:pPr><w:r><w:drawing>"+start+"<wp:extent cx=\""+cx+"\" cy=\""+cy+"\"/><wp:effectExtent l=\"0\" t=\"0\" r=\"0\" b=\"0\"/>"+(positioned?"<wp:wrapNone/>":"")+"<wp:docPr id=\""+(Math.abs(id.hashCode())+1L)+"\" name=\"Source image "+index+"\"/><wp:cNvGraphicFramePr/><a:graphic><a:graphicData uri=\"http://schemas.openxmlformats.org/drawingml/2006/picture\"><pic:pic><pic:nvPicPr><pic:cNvPr id=\"0\" name=\"Source image\"/><pic:cNvPicPr/></pic:nvPicPr><pic:blipFill><a:blip r:embed=\""+id+"\"/><a:stretch><a:fillRect/></a:stretch></pic:blipFill><pic:spPr><a:xfrm><a:off x=\"0\" y=\"0\"/><a:ext cx=\""+cx+"\" cy=\""+cy+"\"/></a:xfrm><a:prstGeom prst=\"rect\"><a:avLst/></a:prstGeom></pic:spPr></pic:pic></a:graphicData></a:graphic>"+(positioned?"</wp:anchor>":"</wp:inline>")+"</w:drawing></w:r></w:p>";}
 static String relationships(JSONObject page,int pageIndex)throws Exception{StringBuilder out=new StringBuilder();int i=0;for(JSONObject b:ordered(page.getJSONArray("blocks"))){if(b.getString("type").equals("image")){String id="p"+pageIndex+"_"+i;out.append("<Relationship Id=\"").append(id).append("\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/image\" Target=\"media/").append(id).append(".png\"/>");}i++;}return out.toString();}
 static String section(double width,double height,boolean last,boolean positioned){String s="<w:sectPr><w:type w:val=\"nextPage\"/><w:pgSz w:w=\""+Math.round(width*20)+"\" w:h=\""+Math.round(height*20)+"\"/><w:pgMar w:top=\"0\" w:right=\"0\" w:bottom=\"0\" w:left=\"0\" w:header=\"0\" w:footer=\"0\"/></w:sectPr>";return last?s:"<w:p><w:pPr>"+s+"</w:pPr></w:p>";}
 static void finish(ZipOutputStream zip,StringBuilder body,StringBuilder rels)throws Exception{
  LayoutWordExporter.entry(zip,"[Content_Types].xml","<Types xmlns=\"http://schemas.openxmlformats.org/package/2006/content-types\"><Default Extension=\"rels\" ContentType=\"application/vnd.openxmlformats-package.relationships+xml\"/><Default Extension=\"xml\" ContentType=\"application/xml\"/><Default Extension=\"png\" ContentType=\"image/png\"/><Override PartName=\"/word/document.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml\"/></Types>");LayoutWordExporter.entry(zip,"_rels/.rels","<Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\"><Relationship Id=\"rId1\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument\" Target=\"word/document.xml\"/></Relationships>");LayoutWordExporter.entry(zip,"word/_rels/document.xml.rels","<Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\">"+rels+"</Relationships>");
  LayoutWordExporter.entry(zip,"word/document.xml","<w:document xmlns:w=\"http://schemas.openxmlformats.org/wordprocessingml/2006/main\" xmlns:v=\"urn:schemas-microsoft-com:vml\" xmlns:r=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships\" xmlns:wp=\"http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing\" xmlns:a=\"http://schemas.openxmlformats.org/drawingml/2006/main\" xmlns:pic=\"http://schemas.openxmlformats.org/drawingml/2006/picture\"><w:body>"+body+"</w:body></w:document>");
 }
}
